    bg = max(counts, key=counts.get)

    for v, c in counts.most_common():
        if v != bg and c > 0:
            marker = v
            break

    # Fill spaces between markers in each row
    for r in range(n):
        markers = [j for j, c in enumerate(result[r]) if c == marker]
        if len(markers) >= 2:
            min_m, max_m = markers[0], markers[-1]
            for i in range(min_m + 1, max_m, 2):
                result[r][i] = 2

    # Find last marker row
    last_marker_row = None
    for r in range(n - 1, -1, -1):
        if any(c == marker for c in result[r]):
            last_marker_row = r
            break

    # Move row only if last marker row has exactly 2 markers
    move_happened = False
    if last_marker_row is not None:
        markers = [j for j, c in enumerate(result[last_marker_row]) if c == marker]
        if len(markers) == 2:
            all_empty_below = all(
                result[r] == [bg] * len(result[0]) 
                for r in range(last_marker_row + 1, n)
            )
            if all_empty_below and last_marker_row > 0:
                result[last_marker_row - 1] = result[last_marker_row][:]
                result[last_marker_row] = [bg] * len(result[0])
                move_happened = True

    # Remove exactly ONE trailing empty row if move happened
    if move_happened and len(result) > 0 and result[-1] == [bg] * len(result[0]):
        result.pop()

    return result
